  const ib=(action,n,label)=>`<button class="icon-button" data-action="${action}" aria-label="${label}" title="${label}">${icon(n)}</button>`;
  const toggle=(label,on=true)=>`<label class="toggle"><input type="checkbox" aria-label="${label}" ${on?'checked':''}><span aria-hidden="true"></span></label>`;
  const compact=n=>Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(n);
  const providers={chatgpt:'ChatGPT',claude:'Claude'};
